<?php if (!empty($uploadMessage)): ?><div class="alert alert-info py-2" role="status"><?= htmlspecialchars((string) $uploadMessage) ?></div><?php endif; ?><div class="row g-3"><?php foreach ($infos as $info): ?><div class="col-12 col-md-6 col-xl-4"><article class="card h-100 shadow-sm"><div class="card-body"><h2 class="h6 mb-2"><a href="<?= htmlspecialchars(url_for('kundeninfos/' . (int) $info->id), ENT_QUOTES) ?>"><?= htmlspecialchars((string) $info->title) ?></a></h2><p class="small text-body-secondary mb-2"><?= htmlspecialchars((string) ($info->updated_at ?: '—')) ?></p><?php if (trim((string) $info->file_name) !== ''): ?><span class="badge text-bg-light border text-truncate mw-100"><i class="fa-solid fa-paperclip me-1" aria-hidden="true"></i><?= htmlspecialchars((string) $info->file_name) ?></span><?php endif; ?><div class="mt-3 d-flex flex-wrap gap-2"><a class="btn btn-sm btn-outline-primary" href="<?= htmlspecialchars(url_for('kundeninfos/' . (int) $info->id), ENT_QUOTES) ?>">Öffnen</a><a class="btn btn-sm btn-outline-secondary" href="<?= htmlspecialchars(url_for('kunden/' . (int) $customer->id . '/infos/' . (int) $info->id . '/bearbeiten'), ENT_QUOTES) ?>">Bearbeiten</a><form class="d-inline" method="post" action="<?= htmlspecialchars(url_for('kunden/' . (int) $customer->id . '/infos/' . (int) $info->id . '/loeschen'), ENT_QUOTES) ?>" onsubmit="return confirm('Diese Kundeninfo wirklich löschen?');"><button class="btn btn-sm btn-outline-danger">Löschen</button></form></div></div></article></div><?php endforeach; ?><?php if ($infos === []): ?><div class="col-12"><div class="alert alert-info">Für diesen Kunden sind noch keine Infos hinterlegt.</div></div><?php endif; ?></div>
